def country():
    for p in ("/etc/matryoshka/country",):
        try: return open(p).read().strip().upper() or "RU"
        except OSError: pass
    return "RU"
def activator_text():
    return ACTIVATOR.get(country(), ACTIVATOR["OTHER"]) + " Матрёшка не поставляет и не скачивает активаторы. " + REVIEW
